 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "covariance.h"

/* Include the Exo-generated kernel header. */
#include "generated/covariance/covariance.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)n;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = ((DATA_TYPE) i*j) / M;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(cov,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("cov");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, cov[i][j]);
    }
  POLYBENCH_DUMP_END("cov");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline covariance kernel written to respect PolyBench's row-major
# layout (data[i][j] has j as the contiguous dimension).  We compute:
#  1) column means,
#  2) center the data in-place,
#  3) covariance = X^T X / (n - 1),
# and then add parallelism via a scheduling pass.

@proc
def kernel_covariance_base(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # ------------------------------------------------------------------
    # 1. Compute column means.
    #    We use a row-major traversal of `data` for better spatial
    #    locality, but for each column j the sequence of additions over
    #    i is identical to the PolyBench reference implementation.
    # ------------------------------------------------------------------

    # Zero-initialize the means.
    for j in seq(0, m):
        mean[j] = 0.0

    # Accumulate sums for each column using row-major accesses to data.
    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    # Finalize the means by dividing by float_n.
    for j in seq(0, m):
        mean[j] = mean[j] / float_n

    # ------------------------------------------------------------------
    # 2. Center the data matrix: subtract mean[j] from each column j.
    #    This loop is already row-major friendly.
    # ------------------------------------------------------------------
    for i in seq(0, n):
        for j in seq(0, m):
            data[i, j] = data[i, j] - mean[j]

    # ------------------------------------------------------------------
    # 3. Compute the covariance matrix:
    #       cov[i,j] = sum_k data[k,i] * data[k,j] / (float_n - 1)
    #    for 0 <= i <= j < m, and enforce symmetry cov[j,i] = cov[i,j].
    #
    #    We precompute (float_n - 1) once, but keep the division inside
    #    the loop so that the arithmetic is semantically equivalent to
    #    the original PolyBench kernel.
    # ------------------------------------------------------------------
    den: DATA_TYPE
    den = float_n - 1.0

    for i in seq(0, m):
        for j in seq(i, m):
            cov[i, j] = 0.0
            for k in seq(0, n):
                cov[i, j] += data[k, i] * data[k, j]
            cov[i, j] = cov[i, j] / den
            cov[j, i] = cov[i, j]

# ----------------------------------------------------------------------
# Scheduling: parallelize the expensive covariance computation.
#
# The dominant cost is the triple loop computing cov[i,j].  Different
# outer-loop iterations over i operate on disjoint (i,j) / (j,i) pairs,
# so they can be safely executed in parallel.  The mean and centering
# phases are left sequential since they are O(n*m) versus O(n*m^2).
# ----------------------------------------------------------------------

kernel_covariance_scheduled = kernel_covariance_base

# Parallelize the outermost covariance loop over `i`.  This lowers
# to an OpenMP-style parallel loop in the generated C; if OpenMP is
# not enabled at compile time, the pragma is ignored and the code
# still runs correctly in serial.
i_cov = kernel_covariance_scheduled.find_loop("for i in _:_ #2")
kernel_covariance_parallel = parallelize_loop(kernel_covariance_scheduled, i_cov)

# Simplify the resulting code to clean up any minor algebra.
kernel_covariance_simplified = simplify(kernel_covariance_parallel)

# Give the final scheduled procedure the name expected by the C driver.
kernel_covariance = rename(kernel_covariance_simplified, "kernel_covariance")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(cov,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);


  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_covariance (/*ctxt=*/NULL, m, n,
                     (DATA_TYPE*)&float_n,
                     (DATA_TYPE*)POLYBENCH_ARRAY(data),
                     (DATA_TYPE*)POLYBENCH_ARRAY(cov),
                     (DATA_TYPE*)POLYBENCH_ARRAY(mean));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(cov)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(cov);
  POLYBENCH_FREE_ARRAY(mean);

  return 0;
}
