def kernel_covariance(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # n is the number of rows (observations), m is the number of columns (variables).
    # We require at least two observations so that (float_n - 1.0) is non-zero.
    assert n > 1

    # -------------------------------------------------------------------------
    # Step 1: compute the mean of each column.
    # We traverse data row-major (i outer, j inner) to improve spatial locality.
