    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    # Normalize to obtain the mean for each column.
    for j in seq(0, m):
        mean[j] = mean[j] / float_n

    # -------------------------------------------------------------------------
    # Step 2: initialize the covariance matrix to zero.
    # We use a full m x m matrix here; symmetry is enforced later.
    # -------------------------------------------------------------------------
    for i in seq(0, m):
        for j in seq(0, m):
            cov[i, j] = 0.0

    # -------------------------------------------------------------------------
    # Step 3: accumulate outer products of centered rows.
    #
    # For each row k, we:
    #   1. Center it: row[j] = data[k, j] - mean[j]
    #   2. Store the centered row back into data[k, j] to preserve
    #      the original kernel’s side-effect on `data`.
    #   3. Accumulate cov[i, j] += row[i] * row[j] for all i <= j.
