    #   cov[i, j] = sum_k (x[k, i] - mean[i]) * (x[k, j] - mean[j])
    # over the upper triangle. Scaling and symmetry are handled in Step 4.
    #
    # Using the temporary buffer `row` keeps the active working set small
    # and accesses both `data` and `row` in a cache-friendly, contiguous way.
    # -------------------------------------------------------------------------
    row: DATA_TYPE[m] @ DRAM

    for k in seq(0, n):
        # Center the k-th row and store it both in `row` and back into `data`.
        for j in seq(0, m):
            row[j] = data[k, j] - mean[j]
            data[k, j] = row[j]

        # Accumulate the contribution of this centered row to the covariance.
        for i in seq(0, m):
            for j in seq(i, m):
                cov[i, j] += row[i] * row[j]

