        cov[i, i] = cov[i, i] / norm_factor

        # Off-diagonal elements: write both (i, j) and (j, i).
        for j in seq(i + 1, m):
            tmp: DATA_TYPE
            tmp = cov[i, j] / norm_factor
            cov[i, j] = tmp
            cov[j, i] = tmp

