from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base kernel: matches the original PolyBench covariance computation.
@proc
def kernel_covariance(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    # Precompute reciprocals once to avoid repeated divisions inside loops
    inv_float_n : DATA_TYPE
    inv_den : DATA_TYPE
    inv_float_n = 1.0 / float_n
    inv_den = 1.0 / (float_n - 1.0)

    # Compute the mean of each column j over all rows i
    for j in seq(0, m):
        mean[j] = 0.0
        for i in seq(0, n):
            mean[j] += data[i, j]
        mean[j] = mean[j] * inv_float_n

    # Center the data by subtracting the mean from each column
    for i in seq(0, n):
        for j in seq(0, m):
            data[i, j] = data[i, j] - mean[j]

    # Compute the covariance matrix (upper triangle) and mirror it to enforce symmetry
    for i in seq(0, m):
        for j in seq(i, m):
            cov[i, j] = 0.0
            for k in seq(0, n):
                cov[i, j] += data[k, i] * data[k, j]
            cov[i, j] = cov[i, j] * inv_den
            cov[j, i] = cov[i, j]

# ------------------------------------------------------------------
# Scheduling for performance
# ------------------------------------------------------------------
# We keep the algorithm identical to the baseline, but:
#  - parallelize the outer covariance loop over i
#  - tile the reduction over k to improve cache behavior and give
#    the backend more opportunity to optimize the innermost loop.

# Parallelize the outer covariance loop over i.
# There are three loops with iterator 'i' in the procedure:
#   0: inner loop of the mean computation (over n)
#   1: outer loop of the centering phase (over n)
#   2: outer loop of the covariance phase (over m)  <-- we want this one
cov_i_loop = kernel_covariance.find_loop("i #2")
kernel_covariance = parallelize_loop(kernel_covariance, cov_i_loop)

# Tile the reduction over k in the covariance computation.
# This improves temporal locality in the data[k, i] / data[k, j] accesses
# and exposes a structured inner loop for the backend to vectorize.
TILE_K = 32  # Tuning knob: tile size along the reduction dimension
k_loop = kernel_covariance.find_loop("k")
kernel_covariance = divide_loop(kernel_covariance, k_loop, TILE_K, ("ko", "ki"), tail="guard")

# Simplify after transformations to clean up loop bounds and expressions.
kernel_covariance = simplify(kernel_covariance)

EXO END
